def tree_view(nodes, revno):
    rows = []
    for node in nodes:
        rows.append({
            'date': format_date(node.timestamp),
            'selected': node.revno == revno,
        })

    roots = [r for r in rows if r.get('parent') is None]
    return roots

class Parser(object):
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.tokens = []

    def advance(self):
        self.pos += 1

    def peek(self):
        return self.text[self.pos]
